    static func response(_ ev: Double) -> [Double] {
        let position = min(100,max(0,(ev+5)*10)), lo = min(99,Int(position)), weight = position-Double(lo)
        func value(_ row: Int, _ i: Int) -> Double { row == 50 ? Double(i)/64 : Double(measured[row][i])/65535 }
        return (0..<count).map { value(lo,$0)*(1-weight)+value(lo+1,$0)*weight }
    }
    private static func linear(_ x: Double) -> Double { x <= 0.04045 ? x/12.92 : pow((x+0.055)/1.055,2.4) }
    private static func encoded(_ x: Double) -> Double { x <= 0.0031308 ? x*12.92 : 1.055*pow(x,1/2.4)-0.055 }
    static func map(_ x: Double, response values: [Double], ev: Double) -> Double {
        if x < 0 { return x*pow(2,ev) }
        if x > 1 {
            // Extend the endpoint tangent, rather than clipping ICC/WB overrange.
            let slope = (linear(values[64])-linear(values[63]))/(1-linear(63.0/64))
            return linear(values[64])+(x-1)*slope
        }
        let points = values.enumerated().map { CurvePoint(x:Double($0.offset)/64,y:$0.element) }
        return linear(TonalPipeline.evaluate(points,at:encoded(x)))
    }
    static func baseTransform(_ input: SIMD3<Double>, ev: Double) -> SIMD3<Double> {
        guard ev != 0 else { return input }
        func matrix(_ rows: [SIMD3<Double>], _ c: SIMD3<Double>) -> SIMD3<Double> {
            SIMD3(rows[0].x*c.x+rows[0].y*c.y+rows[0].z*c.z,
                rows[1].x*c.x+rows[1].y*c.y+rows[1].z*c.z,
                rows[2].x*c.x+rows[2].y*c.y+rows[2].z*c.z)
        }
        let c = matrix(toWide,input), low = min(c.x,min(c.y,c.z)), high = max(c.x,max(c.y,c.z))
        let values = response(ev), a = map(low,response:values,ev:ev), b = map(high,response:values,ev:ev)
        let mapped = high > low ? SIMD3(repeating:a)+(c-SIMD3(repeating:low))*((b-a)/(high-low)) : SIMD3(repeating:a)
        return matrix(fromWide,mapped)
    }
    static func transform(_ input: SIMD3<Double>, ev: Double) throws -> SIMD3<Double> {
        guard ev.isFinite, (-5...5).contains(ev), (0..<3).allSatisfy({ input[$0].isFinite }) else { throw LRCError(L10n.text("app.invalidExposureParameters", defaultValue: "Invalid exposure parameters")) }
        guard ev != 0 else { return input }
        let e = SIMD3(encoded(input.x), encoded(input.y), encoded(input.z))
        return try baseTransform(input, ev: ev) + RasterExposureColour.correction(e, ev: ev)
    }
    static func apply(_ input: CIImage, ev: Double) throws -> CIImage {
        guard ev.isFinite, (-5...5).contains(ev) else { throw LRCError(L10n.text("app.invalidExposureParameters", defaultValue: "Invalid exposure parameters")) }
        guard ev != 0 else { return input }
        let values = response(ev)
        let packed = (0..<17).map { block in
            let i = block*4
            return CIVector(x:values[min(64,i)],y:values[min(64,i+1)],z:values[min(64,i+2)],w:values[min(64,i+3)])
        }
        let base = try SpatialDevelopPipeline.run("rasterExposure",extent:input.extent,[input]+packed+[ev])
        return try RasterExposureColour.apply(input, base: base, ev: ev)
    }
